async function loadCloud(){const [cr,fr]=await Promise.all([supabase.from('chats').select('id,title,messages,updated_at,folder_id').order('updated_at',{ascending:false}),supabase.from('chat_folders').select('id,name,updated_at').order('name')]);if(cr.error){alert('Could not load cloud history: '+cr.error.message);return}if(fr.error){alert('Could not load folders. Run the updated supabase.sql migration first. '+fr.error.message);return}state.chats=cr.data||[];state.folders=fr.data||[];if(!state.chats.some(c=>c.id===state.active))state.active=state.chats[0]?.id||null;if(state.showHome===undefined)state.showHome=!state.active;if(state.activeFolder&&!state.folders.some(f=>f.id===state.activeFolder))state.activeFolder=null;save()}
function syncChat(chat){if(!authenticated)return Promise.resolve();const snapshot={id:chat.id,title:chat.title,messages:structuredClone(chat.messages),folder_id:chat.folder_id||null,updated_at:new Date().toISOString()};syncQueue=syncQueue.catch(()=>{}).then(async()=>{const {error}=await supabase.from('chats').upsert(snapshot);if(error)throw error});syncQueue.catch(e=>{$('status').textContent='Sync failed: '+e.message});return syncQueue}
