// Paste images / files from the clipboard (ignored when the clipboard also carries text, so normal pasting still works)
document.addEventListener('paste',async e=>{if(!authenticated||(e.target instanceof Element&&e.target.closest('dialog')))return;const files=[...(e.clipboardData?.files||[])].filter(f=>f.type.startsWith('image/')||/\.(txt|md|csv|json|pdf|png|jpe?g|webp|gif)$/i.test(f.name));if(!files.length||e.clipboardData.getData('text/plain'))return;e.preventDefault();for(const f of files){const generic=!f.name||/^image\.(png|jpe?g|gif|webp)$/i.test(f.name);await addPending(f,generic?`pasted-image-${new Date().toTimeString().slice(0,8).replace(/:/g,'')}-${pendingFiles.length+1}.jpg`:null)}$('prompt').focus()});
