$('tokenHide').onclick=()=>{$('tokenWidget').hidden=true;$('tokenShow').hidden=false;localStorage.setItem('aihub-token-hidden','1')};$('tokenShow').onclick=()=>{$('tokenWidget').hidden=false;$('tokenShow').hidden=true;localStorage.removeItem('aihub-token-hidden')};
$('tokenDrag').addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const w=$('tokenWidget'),r=w.getBoundingClientRect();const dx=e.clientX-r.left,dy=e.clientY-r.top;w.style.right='auto';w.style.bottom='auto';function move(ev){w.style.left=Math.max(0,Math.min(innerWidth-w.offsetWidth,ev.clientX-dx))+'px';w.style.top=Math.max(0,Math.min(innerHeight-w.offsetHeight,ev.clientY-dy))+'px'}function up(){document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);localStorage.setItem('aihub-token-pos',JSON.stringify({left:w.style.left,top:w.style.top}))}document.addEventListener('pointermove',move);document.addEventListener('pointerup',up)});
