function updateUploadHint(){const provider=$('provider').value,model=$('model').value,img=supportsImages(provider,model);$('uploadHint').textContent=`Selected: ${provider} · ${model}. Attach, drag in or paste (Ctrl/Cmd+V) images — ${img===true?'this model accepts images':img===false?'this model is not known to accept images':'image support for this model is unknown'}; images are shrunk in your browser before sending. Text/code/PDF files (.txt, .md, .csv, .json, .js, .ts, .html, .css, .xml, .py, .java, .sql, .log, .pdf) have their text extracted and sent in the prompt. Audio/video/Word/Excel files are not supported. Limit: 100 MB per file, 4 files per message, 40,000 extracted characters per text file. Scanned PDFs may have no extractable text.`}
