const userMsg={role:'user',content:displayText,files:textFiles.map(f=>({name:f.name}))};if(imgFiles.length)userMsg.images=imgFiles.map(f=>({name:f.name,src:f.stored}));
const base=editingIndex!==null?c.messages.slice(0,editingIndex):c.messages.slice(),all=[...base,userMsg],lastIdx=all.length-1;
// Only the two most recent image-bearing messages are re-sent with their pictures; older ones become a text note to keep requests small.
const withImg=new Set(all.map((x,i)=>x.role==='user'&&x.images?.length?i:-1).filter(i=>i>=0).slice(-2));
const messages=all.map((msg,i)=>{const text=msg.role==='user'&&i===lastIdx?fullText:msg.content;if(msg.role==='user'&&msg.images?.length){if(withImg.has(i)){const urls=i===lastIdx?imgFiles.map(f=>f.dataUrl):msg.images.map(x=>x.src);return {role:'user',content:[{type:'text',text:text||'Please look at the attached image(s).'},...urls.map(u=>({type:'image_url',image_url:{url:u}}))]}}return {role:'user',content:(text?text+'\n\n':'')+`[${msg.images.length} image(s) were attached earlier in this chat: ${msg.images.map(x=>x.name).join(', ')}]`}}return {role:msg.role,content:text}});
const memory=crossChatContext(promptText||files.map(f=>f.name).join(' '),c);if(memory)messages.unshift({role:'system',content:'Use the following cross-chat context only when relevant. Do not claim it was said in the current chat.\n\n'+memory});
const payload=JSON.stringify({provider:p,model:m,messages});if(payload.length>5400000){alert('This message is too large to send (the images are big). Remove an image or two and try again.');return}
